const TZ = 'Asia/Ho_Chi_Minh';
// The NocoDB node nests a row as { id, id_fields, fields }.
const rowsOf = (name) => $(name).all()
  .map((i) => i.json || {})
  .filter((j) => j.id !== undefined && j.id !== null)
  .map((j) => ({ Id: j.id, ...(j.fields || {}) }));
const settingsOf = (name) => Object.fromEntries(
  rowsOf(name).filter((r) => r.key).map((r) => [r.key, (r.value ?? '').toString().trim()]));
const parseDt = (s) => DateTime.fromISO(String(s || '').trim().replace(' ', 'T'), { setZone: true }).setZone(TZ);
const parseDate = (s) => DateTime.fromISO(String(s || '').trim().slice(0, 10), { zone: TZ });

const c = $('When called').first().json;
// Read here, not in plan month: a cycle planned earlier in the same run is already saved.
const recent = rowsOf('Load posts').map((p) => ({ date: parseDt(p.publish_at).toISODate(), kind: p.kind, title: p.title }));
const o = c.offer;
const lines = (s) => (s || '').split('\n').filter(Boolean).map((l) => `- ${l}`).join('\n');
const prompt = [
  `Brand: ${c.page_name}. Language: ${c.language}.`,
  '',
  `Offer: ${o.title}`,
  `Product: ${o.product}. Deal: ${o.offer}. Reason (${o.reason_type}): ${o.reason}`,
  `Launch ${o.launch_date}, reminder ${o.reminder_date}, ends ${o.ends_on}.`,
  `Must know before the offer:\n${lines(o.must_know)}`,
  `Must feel before the offer:\n${lines(o.must_feel)}`,
  '',
  `Slots (${c.slots.length}):`,
  ...c.slots.map((s) => `- ${s.date} ${s.weekday}: ${s.kind === 'open' ? 'open (education or story)' : s.kind}`),
  '',
  `Posts already planned or published (do not repeat their titles, angles or stories):\n${recent.map((r) => `- ${r.date} ${r.kind}: ${r.title}`).join('\n') || '(none)'}`,
  '',
  `Story bank (true events):\n${c.stories.map((s) => `#${s.id}: ${s.text}`).join('\n') || '(empty)'}`,
  '',
  `Rules learned from past months:\n${c.rules || '(none yet)'}`,
  '',
  `Brand docs:\n${c.brand}`,
].join('\n');
return [{ json: { prompt } }];

const parseJson = (s) => {
  const t = String(s || '').replace(/```(?:json)?/gi, '');
  const a = t.indexOf('{');
  const b = t.lastIndexOf('}');
  if (a < 0 || b <= a) throw new Error('no JSON object in the model output');
  return JSON.parse(t.slice(a, b + 1));
};

// Hard checks: one post per slot, sales only on the launch and reminder slots.
const c = $('When called').first().json;
// The repair model answers in JSON mode: the chain node returns the parsed object, not { text }.
const raw = $json.text === undefined ? JSON.stringify($json) : String($json.text);
const errors = [];
let pieces = [];
try {
  pieces = parseJson(raw).pieces;
  if (!Array.isArray(pieces)) throw new Error('"pieces" is not an array');
} catch (e) {
  errors.push(`Output is not the JSON shape asked for: ${e.message}`);
  pieces = [];
}

const s = (v) => (v ?? '').toString().trim();
const byDate = new Map(pieces.map((p) => [s(p.date), p]));
const SELLING = /(\d+\s?%|giảm giá|khuyến mãi|ưu đãi|mã giảm|voucher|đăng ký ngay|mua ngay|chốt đơn)/i;
const clean = [];
if (!errors.length) {
  if (pieces.length !== c.slots.length) errors.push(`Expected ${c.slots.length} entries, one per slot; got ${pieces.length}.`);
  for (const slot of c.slots) {
    const p = byDate.get(slot.date);
    if (!p) { errors.push(`No entry for slot ${slot.date}.`); continue; }
    const kind = s(p.kind);
    if (slot.kind === 'open' && !['education', 'story'].includes(kind)) errors.push(`${slot.date}: an open slot must be education or story, not "${kind}".`);
    if (slot.kind !== 'open' && kind !== slot.kind) errors.push(`${slot.date}: this slot is ${slot.kind}.`);
    if (!s(p.title)) errors.push(`${slot.date}: title is empty.`);
    if (s(p.brief).length < 60) errors.push(`${slot.date}: brief is too thin to write from.`);
    if (['education', 'story'].includes(kind) && SELLING.test(s(p.brief))) errors.push(`${slot.date}: an ${kind} brief must not mention prices, discounts or buying.`);
    clean.push({
      date: slot.date,
      kind,
      title: s(p.title),
      sets_up: s(p.sets_up),
      brief: s(p.brief),
      material_question: s(p.material_question),
      story_ids: (Array.isArray(p.story_ids) ? p.story_ids : []).map(Number).filter((n) => Number.isInteger(n) && n > 0),
    });
  }
  const extra = pieces.filter((p) => !c.slots.some((slot) => slot.date === s(p.date)));
  if (extra.length) errors.push(`Entries for dates that are not slots: ${extra.map((p) => s(p.date)).join(', ')}.`);
  let run = 0;
  for (const p of clean) {
    run = p.kind === 'education' ? run + 1 : 0;
    if (run > 3) { errors.push(`More than three education posts in a row around ${p.date}.`); break; }
  }
}

if (errors.length && $runIndex >= 1) throw new Error('Plan still invalid after a repair: ' + errors.join(' '));
return [{ json: { valid: errors.length === 0, errors, pieces: clean, raw } }];

