    material_question: p.material_question,
  },
}));

const c = $('When called').first().json;
return [{
  json: {
    offer_id: c.offer.Id,
    offer_title: c.offer.title,
    launch_date: c.offer.launch_date,
    reminder_date: c.offer.reminder_date,
    pieces: $('Piece rows').all().map((i, n) => ({
      id: $('Save pieces').all()[n].json.id,
      date: i.json.publish_at.slice(0, 10),
